import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.BXzK3EA4.js";const S=JSON.parse('{"title":"거점과 영토 규칙","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Rules-Strongholds.md","filePath":"rules/Rules-Strongholds.md"}'),o={name:"rules/Rules-Strongholds.md"};function l(h,t,i,s,n,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="거점과-영토-규칙" tabindex="-1">거점과 영토 규칙 <a class="header-anchor" href="#거점과-영토-규칙" aria-label="Permalink to &quot;거점과 영토 규칙&quot;">​</a></h1><blockquote><p>출처: docs/game-logic/Strongholds-and-Territory.md — 계약 수치는 구현 상수를 우선한다.</p></blockquote><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>역은 점령만으로 완성되는 깃발이 아니다. 사람·시설·연결을 다시 켜야 전략 거점으로 선다. 점유 뒤 안정화와 영토 통합은 4방향 시야와 연결이 맡는다.</p><h2 id="핵심-수치" tabindex="-1">핵심 수치 <a class="header-anchor" href="#핵심-수치" aria-label="Permalink to &quot;핵심 수치&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th style="text-align:right;">값</th><th style="text-align:right;">범위</th></tr></thead><tbody><tr><td>권위 <code>A</code></td><td style="text-align:right;">점령 직후 최대 45</td><td style="text-align:right;">0~100</td></tr><tr><td>협력 <code>L</code></td><td style="text-align:right;">강제 점령 기본값 20</td><td style="text-align:right;">0~100</td></tr><tr><td>시설 상태 <code>R</code></td><td style="text-align:right;">—</td><td style="text-align:right;">0~100</td></tr><tr><td>연결도 <code>K</code></td><td style="text-align:right;">—</td><td style="text-align:right;">0~1</td></tr><tr><td>부족도 <code>S</code></td><td style="text-align:right;">—</td><td style="text-align:right;">0~1</td></tr><tr><td>과확장 <code>O</code></td><td style="text-align:right;">—</td><td style="text-align:right;">0~2</td></tr><tr><td>일반 역 시설 슬롯</td><td style="text-align:right;">2</td><td style="text-align:right;">1~4</td></tr><tr><td>환승역 시설 슬롯</td><td style="text-align:right;">3</td><td style="text-align:right;">1~4</td></tr><tr><td>주요 사업 작업량</td><td style="text-align:right;">100</td><td style="text-align:right;">40~240</td></tr><tr><td>통합 권위</td><td style="text-align:right;">65</td><td style="text-align:right;">0~100</td></tr><tr><td>통합 협력</td><td style="text-align:right;">55</td><td style="text-align:right;">0~100</td></tr><tr><td>통합 시설</td><td style="text-align:right;">60</td><td style="text-align:right;">0~100</td></tr><tr><td>통합 유지 기간</td><td style="text-align:right;">3일</td><td style="text-align:right;">1~7일</td></tr><tr><td>안정화 진입 권위</td><td style="text-align:right;">50</td><td style="text-align:right;">—</td></tr><tr><td>안정화 진입 협력</td><td style="text-align:right;">35</td><td style="text-align:right;">—</td></tr><tr><td>통합 연결도</td><td style="text-align:right;">0.5</td><td style="text-align:right;">—</td></tr><tr><td>통합 부족도 상한</td><td style="text-align:right;">0.25</td><td style="text-align:right;">—</td></tr><tr><td>부족 판정</td><td style="text-align:right;">식량 또는 전력 75% 미만</td><td style="text-align:right;">—</td></tr><tr><td>압박 부채 기본값</td><td style="text-align:right;">0</td><td style="text-align:right;">0~100</td></tr><tr><td>압박 부채 사건 임계</td><td style="text-align:right;">100</td><td style="text-align:right;">—</td></tr></tbody></table><h2 id="조항" tabindex="-1">조항 <a class="header-anchor" href="#조항" aria-label="Permalink to &quot;조항&quot;">​</a></h2><h3 id="rstrongholds-01-거점의-성격" tabindex="-1">RSTRONGHOLDS-01 거점의 성격 <a class="header-anchor" href="#rstrongholds-01-거점의-성격" aria-label="Permalink to &quot;RSTRONGHOLDS-01 거점의 성격&quot;">​</a></h3><p>역은 점령 즉시 완성되는 깃발이 아니다. 사람·시설·연결을 다시 작동시켜야 전략 거점으로 선다.</p><h3 id="rstrongholds-02-권위-a" tabindex="-1">RSTRONGHOLDS-02 권위 A <a class="header-anchor" href="#rstrongholds-02-권위-a" aria-label="Permalink to &quot;RSTRONGHOLDS-02 권위 A&quot;">​</a></h3><p>권위 <code>A</code>의 범위는 0~100이다. 점령 직후 최댓값은 45로 고정한다. 순찰·협약 집행·적대 활동 억제에 권위를 쓴다.</p><h3 id="rstrongholds-03-협력-l" tabindex="-1">RSTRONGHOLDS-03 협력 L <a class="header-anchor" href="#rstrongholds-03-협력-l" aria-label="Permalink to &quot;RSTRONGHOLDS-03 협력 L&quot;">​</a></h3><p>협력 <code>L</code>의 범위는 0~100이다. 강제 점령의 기본값은 20으로 둔다. 노동·정보 제공·통치 수용은 협력에 따른다.</p><h3 id="rstrongholds-04-시설-상태-r" tabindex="-1">RSTRONGHOLDS-04 시설 상태 R <a class="header-anchor" href="#rstrongholds-04-시설-상태-r" aria-label="Permalink to &quot;RSTRONGHOLDS-04 시설 상태 R&quot;">​</a></h3><p>시설 상태 <code>R</code>의 범위는 0~100이다. 지역 서비스와 노선 서비스가 이 값에 묶인다.</p><h3 id="rstrongholds-05-연결도-k" tabindex="-1">RSTRONGHOLDS-05 연결도 K <a class="header-anchor" href="#rstrongholds-05-연결도-k" aria-label="Permalink to &quot;RSTRONGHOLDS-05 연결도 K&quot;">​</a></h3><p>연결도 <code>K</code>의 범위는 0~1이다. 식은 <code>K = clamp(max_path(min_edge_capacity), 0, 1)</code>을 따른다. 합법 보급 경로마다 가장 좁은 연결의 처리율을 구한 뒤 그중 가장 큰 값을 <code>K</code>로 쓴다.</p><h3 id="rstrongholds-06-봉쇄-연결" tabindex="-1">RSTRONGHOLDS-06 봉쇄 연결 <a class="header-anchor" href="#rstrongholds-06-봉쇄-연결" aria-label="Permalink to &quot;RSTRONGHOLDS-06 봉쇄 연결&quot;">​</a></h3><p>봉쇄된 연결은 삭제하지 않는다. <code>K=0</code>의 원인과 복구 조건을 보존한다.</p><h3 id="rstrongholds-07-부족도-s" tabindex="-1">RSTRONGHOLDS-07 부족도 S <a class="header-anchor" href="#rstrongholds-07-부족도-s" aria-label="Permalink to &quot;RSTRONGHOLDS-07 부족도 S&quot;">​</a></h3><p>부족도 <code>S</code>의 범위는 0~1이다. 충족률은 수요가 0이면 1이고 아니면 <code>clamp(공급/수요, 0, 1)</code>을 쓴다. <code>S</code>는 <code>1 - min(충족률(식량공급, 식량수요), 충족률(전력공급, 전력수요))</code>로 계산한다.</p><h3 id="rstrongholds-08-0나누기-금지" tabindex="-1">RSTRONGHOLDS-08 0나누기 금지 <a class="header-anchor" href="#rstrongholds-08-0나누기-금지" aria-label="Permalink to &quot;RSTRONGHOLDS-08 0나누기 금지&quot;">​</a></h3><p>수요가 0인 자원은 충족률 1로 둔다. 부족 기여는 0이며 어떤 경우에도 0으로 나누지 않는다.</p><h3 id="rstrongholds-09-과확장-o" tabindex="-1">RSTRONGHOLDS-09 과확장 O <a class="header-anchor" href="#rstrongholds-09-과확장-o" aria-label="Permalink to &quot;RSTRONGHOLDS-09 과확장 O&quot;">​</a></h3><p>과확장 <code>O</code>의 범위는 0~2이다. 물류와 기반 시설의 공유 척도를 그대로 가져온다. 통치부담과 행정역량은 <code>부담비율(통치부담, 행정역량)</code> 항으로 들어간다.</p><h3 id="rstrongholds-10-과확장-산식" tabindex="-1">RSTRONGHOLDS-10 과확장 산식 <a class="header-anchor" href="#rstrongholds-10-과확장-산식" aria-label="Permalink to &quot;RSTRONGHOLDS-10 과확장 산식&quot;">​</a></h3><p>통치부담 4.5와 행정역량 3이면 부담비율은 <code>4.5/3=1.5</code>이다. 물류·귀환 부담 비율이 그보다 작으면 <code>O=clamp(1.5-1,0,2)=0.5</code>가 된다. 과확장은 모든 거점의 안정화와 수송에 감점을 남긴다.</p><h3 id="rstrongholds-11-시설-슬롯" tabindex="-1">RSTRONGHOLDS-11 시설 슬롯 <a class="header-anchor" href="#rstrongholds-11-시설-슬롯" aria-label="Permalink to &quot;RSTRONGHOLDS-11 시설 슬롯&quot;">​</a></h3><p>일반 역 시설 슬롯의 기본값은 2다. 환승역 시설 슬롯의 기본값은 3이다. 둘 다 최솟값 1 최댓값 4를 지킨다.</p><h3 id="rstrongholds-12-주요-사업-작업량" tabindex="-1">RSTRONGHOLDS-12 주요 사업 작업량 <a class="header-anchor" href="#rstrongholds-12-주요-사업-작업량" aria-label="Permalink to &quot;RSTRONGHOLDS-12 주요 사업 작업량&quot;">​</a></h3><p>주요 사업 작업량의 기본값은 100이다. 최솟값 40 최댓값 240을 벗어나지 못한다.</p><h3 id="rstrongholds-13-단계-사슬" tabindex="-1">RSTRONGHOLDS-13 단계 사슬 <a class="header-anchor" href="#rstrongholds-13-단계-사슬" aria-label="Permalink to &quot;RSTRONGHOLDS-13 단계 사슬&quot;">​</a></h3><p>점령지는 <code>분쟁 → 점령 → 안정화 → 통합</code>을 거친다. 전투·협상 결과가 분쟁에서 점령으로 넘긴다.</p><h3 id="rstrongholds-14-안정화-진입" tabindex="-1">RSTRONGHOLDS-14 안정화 진입 <a class="header-anchor" href="#rstrongholds-14-안정화-진입" aria-label="Permalink to &quot;RSTRONGHOLDS-14 안정화 진입&quot;">​</a></h3><p>점령에서 안정화로 가려면 <code>A&gt;=50</code>과 <code>L&gt;=35</code>를 동시에 만족해야 한다.</p><h3 id="rstrongholds-15-통합-조건" tabindex="-1">RSTRONGHOLDS-15 통합 조건 <a class="header-anchor" href="#rstrongholds-15-통합-조건" aria-label="Permalink to &quot;RSTRONGHOLDS-15 통합 조건&quot;">​</a></h3><p>통합은 <code>A&gt;=65</code> <code>L&gt;=55</code> <code>R&gt;=60</code> <code>K&gt;=0.5</code> <code>S&lt;=0.25</code>를 3일 연속 채워야 성립한다. 통합 권위 기본값은 65 협력 55 시설 60으로 둔다. 통합 유지 기간 기본값은 3일이고 범위는 1~7일이다.</p><h3 id="rstrongholds-16-단계-후퇴" tabindex="-1">RSTRONGHOLDS-16 단계 후퇴 <a class="header-anchor" href="#rstrongholds-16-단계-후퇴" aria-label="Permalink to &quot;RSTRONGHOLDS-16 단계 후퇴&quot;">​</a></h3><p>통합에서 부족·고립·과확장이 겹치면 안정화로 물러난다. 권위가 붕괴하면 안정화는 점령으로 떨어진다. 수비·통치를 잃으면 점령은 분쟁으로 되돌린다.</p><h3 id="rstrongholds-17-부족-상태" tabindex="-1">RSTRONGHOLDS-17 부족 상태 <a class="header-anchor" href="#rstrongholds-17-부족-상태" aria-label="Permalink to &quot;RSTRONGHOLDS-17 부족 상태&quot;">​</a></h3><p>식량 또는 전력이 75% 미만이면 부족 상태가 붙는다. 권위와 협력은 그때 하락한다.</p><h3 id="rstrongholds-18-완전-고립" tabindex="-1">RSTRONGHOLDS-18 완전 고립 <a class="header-anchor" href="#rstrongholds-18-완전-고립" aria-label="Permalink to &quot;RSTRONGHOLDS-18 완전 고립&quot;">​</a></h3><p>완전 고립이면 수입과 수출은 0이다. 현지 비축과 발전은 계속 작동한다.</p><h3 id="rstrongholds-19-과확장의-원인" tabindex="-1">RSTRONGHOLDS-19 과확장의 원인 <a class="header-anchor" href="#rstrongholds-19-과확장의-원인" aria-label="Permalink to &quot;RSTRONGHOLDS-19 과확장의 원인&quot;">​</a></h3><p>과확장은 영토 상한이 아니다. 담당자·주둔군·연결 부족에서 발생한다.</p><h3 id="rstrongholds-20-동일일-정산-순서" tabindex="-1">RSTRONGHOLDS-20 동일일 정산 순서 <a class="header-anchor" href="#rstrongholds-20-동일일-정산-순서" aria-label="Permalink to &quot;RSTRONGHOLDS-20 동일일 정산 순서&quot;">​</a></h3><p>같은 날 여러 거점이 임계치를 넘으면 안정된 거점 ID 순서로 정산한다.</p><h3 id="rstrongholds-21-무전력-시설" tabindex="-1">RSTRONGHOLDS-21 무전력 시설 <a class="header-anchor" href="#rstrongholds-21-무전력-시설" aria-label="Permalink to &quot;RSTRONGHOLDS-21 무전력 시설&quot;">​</a></h3><p>무전력 시설만 있는 역은 전력 수요를 0으로 둔다. 전력 충족률은 1이라 부족도 <code>S</code>에 보태지 않는다. 전력 서비스 발생은 인정하지 않는다.</p><h3 id="rstrongholds-22-압박-부채" tabindex="-1">RSTRONGHOLDS-22 압박 부채 <a class="header-anchor" href="#rstrongholds-22-압박-부채" aria-label="Permalink to &quot;RSTRONGHOLDS-22 압박 부채&quot;">​</a></h3><p>압박 부채 <code>PressureDebt</code>의 기본값은 0이며 범위는 0~100이다. 권위·협력 저하와 가시성·적대 인접·과확장으로 쌓이고 주둔 커버와 연결도 <code>K</code>로 줄어든다. 부채가 100에 도달하면 원인에 맞는 사건을 하나 예약하고 부채 100을 뺀다.</p><h3 id="rstrongholds-23-결정론" tabindex="-1">RSTRONGHOLDS-23 결정론 <a class="header-anchor" href="#rstrongholds-23-결정론" aria-label="Permalink to &quot;RSTRONGHOLDS-23 결정론&quot;">​</a></h3><p>동일한 입력은 항상 같은 결과를 낸다. 현지 식량·발전·수리반이 남아 있으면 복구는 계속된다.</p><h3 id="rstrongholds-24-부족도-예시" tabindex="-1">RSTRONGHOLDS-24 부족도 예시 <a class="header-anchor" href="#rstrongholds-24-부족도-예시" aria-label="Permalink to &quot;RSTRONGHOLDS-24 부족도 예시&quot;">​</a></h3><p>식량 40/100 전력 60/100이면 <code>S = 1 - min(0.4, 0.6) = 0.6</code>이 나온다. 합법 경로가 없으면 <code>K=0</code>을 쓴다. 세 조건이 겹친 역은 통합 조건을 만족할 수 없다.</p><h2 id="판정-순서" tabindex="-1">판정 순서 <a class="header-anchor" href="#판정-순서" aria-label="Permalink to &quot;판정 순서&quot;">​</a></h2><ol><li>자원 배분을 수행한다. 충족률과 부족도 <code>S</code>·연결도 <code>K</code>를 이 단계에서 확정한다.</li><li>전투 결과를 반영한다.</li><li>권위·협력·시설을 갱신한다.</li><li>단계 전이를 적용한다. 같은 날 여러 거점이 임계를 넘으면 안정된 거점 ID 순서로 정산한다.</li><li>사건을 예약한다. 압박 부채가 100이면 원인에 맞는 사건 하나를 넣고 부채 100을 뺀다.</li></ol><h2 id="금지-사항" tabindex="-1">금지 사항 <a class="header-anchor" href="#금지-사항" aria-label="Permalink to &quot;금지 사항&quot;">​</a></h2><ul><li>점령 즉시 완성된 깃발로 역을 취급하지 말 것</li><li>봉쇄된 연결을 삭제하지 말 것</li><li>수요 0에서 0으로 나누지 말 것</li><li>과확장을 영토 상한으로 쓰지 말 것</li><li>무전력 시설만 있는 역에 전력 서비스가 생긴 것으로 보지 말 것</li><li>동일 입력에 다른 결과를 내지 말 것</li><li>통합 조건 미달 거점을 통합으로 유지하지 말 것</li><li>설계 가정 수치를 구현 상수보다 앞세우지 말 것</li></ul><h2 id="출처" tabindex="-1">출처 <a class="header-anchor" href="#출처" aria-label="Permalink to &quot;출처&quot;">​</a></h2><ul><li><code>docs/game-logic/Strongholds-and-Territory.md</code></li><li>원문 수치는 모두 첫 프로토타입용 설계 가정이다.</li><li>계약·잠긴 수치와 맞서는 다른 값은 원문에 없었다.</li><li>구현 상수가 있으면 그 값을 우선한다.</li></ul>',61)])])}const R=e(o,[["render",l]]);export{S as __pageData,R as default};
